<?php $page='dashboard';require __DIR__.'/_head.php';$counts=['Projects'=>db()->query('SELECT COUNT(*) c FROM projects')->fetch()['c'],'Posts'=>db()->query('SELECT COUNT(*) c FROM posts')->fetch()['c'],'Categories'=>db()->query('SELECT COUNT(*) c FROM categories')->fetch()['c'],'New messages'=>db()->query("SELECT COUNT(*) c FROM messages WHERE status='new'")->fetch()['c']];$recent=db()->query('SELECT * FROM messages ORDER BY id DESC LIMIT 8')->fetchAll();?><div class="topbar"><div><h1>Dashboard</h1><p class="muted">Welcome back, <?=e($_SESSION['admin_name']??'Admin')?>.</p></div><a class="btn primary" href="../" target="_blank">Open portfolio ↗</a></div><div class="grid"><?php foreach($counts as $k=>$v):?><div class="card"><span class="muted"><?=e($k)?></span><b><?=e($v)?></b></div><?php endforeach;?></div><div class="panel" style="margin-top:20px"><h2>Recent enquiries</h2><table class="table"><tr><th>Name</th><th>Email</th><th>Subject</th><th>Status</th><th>Date</th></tr><?php foreach($recent as $m):?><tr><td><?=e($m['name'])?></td><td><?=e($m['email'])?></td><td><?=e($m['subject'])?></td><td><?=e($m['status'])?></td><td><?=e($m['created_at'])?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/_foot.php';
